def clean(s):
    s=re.sub(r'<[^>]+>',' ',s or '')
    return html.escape(re.sub(r'\s+',' ',s).strip())

def year(it):
    m=re.search(r'20\d\d',it.get('published','') or it.get('date','') or '')
    return m.group(0) if m else ''

