css = r'''
:root{--bg:#0d1117;--slide:#0f172a;--bg-2:#161b22;--bg-3:#1f2937;--text:#e6edf3;--ink-2:#c9d1d9;--muted:#8b949e;--line:#30363d;--blue:#7dd3fc;--purple:#a78bfa;--green:#10b981;--yellow:#f59e0b;--red:#ef4444;--pink:#ec4899}
*{box-sizing:border-box} html,body{width:100%;height:100%;margin:0;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;overflow:hidden;font-size:15px;line-height:1.55;touch-action:pan-y}.slide{position:absolute;inset:0;display:none;padding:58px 62px 78px;overflow:hidden;background:radial-gradient(ellipse 820px 520px at 28% 18%,rgba(125,211,252,.10),transparent 60%),radial-gradient(ellipse 680px 460px at 84% 78%,rgba(167,139,250,.10),transparent 62%),linear-gradient(180deg,#0f172a 0%,#0d1117 100%)}.slide.active{display:block}.slide.cover{display:none}.slide.cover.active{display:flex;flex-direction:column;justify-content:center}.slide.tight{padding:50px 52px 72px}.slide.tight.denser{padding:44px 44px 70px}h1{font-size:34px;line-height:1.12;margin:0 0 16px;letter-spacing:-.02em}h3{font-size:17px;margin:0 0 8px;color:var(--blue)}p,li{line-height:1.45}.subtitle{font-size:20px;color:var(--muted);margin:0 0 18px}.meta{display:flex;gap:12px;flex-wrap:wrap;margin-top:22px}.meta span,.tag{border:1px solid var(--line);background:rgba(255,255,255,.05);border-radius:999px;padding:7px 12px;color:var(--muted)}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{background:rgba(255,255,255,.04);border:1px solid var(--line);border-radius:10px;padding:14px 16px;box-shadow:none}.card ul{margin:6px 0 0;padding-left:18px}.card li{margin:5px 0}.callout{margin-top:16px;border-left:4px solid var(--yellow);background:rgba(251,191,36,.09);padding:12px 16px;border-radius:10px}.note{color:var(--muted);font-size:13.5px}.pipeline{display:flex;align-items:stretch;gap:8px;background:rgba(0,0,0,.22);border:1px solid var(--line);border-radius:16px;padding:14px}.pipeline div{flex:1;text-align:center;padding:12px 8px;border-radius:12px;background:rgba(125,211,252,.09);border:1px solid rgba(125,211,252,.28);font-weight:700}.pipeline span{display:block;color:var(--muted);font-size:12px;font-weight:400;margin-top:4px}.pipeline b{align-self:center;color:var(--yellow);font-size:24px}.timeline{display:grid;gap:14px}.timeline div{display:grid;grid-template-columns:110px 1fr;gap:16px;align-items:center;background:rgba(255,255,255,.05);border:1px solid var(--line);border-radius:14px;padding:15px}.timeline b{font-size:28px;color:var(--yellow)}table{width:100%;border-collapse:collapse;background:rgba(0,0,0,.18);border-radius:14px;overflow:hidden}th,td{border:1px solid var(--line);padding:8px 10px;text-align:left;vertical-align:top}th{background:rgba(125,211,252,.12);color:var(--blue)}.tight.denser table{font-size:12.5px}.tight.denser th,.tight.denser td{padding:5px 7px;line-height:1.28}.diagram{border:1px solid var(--line);border-radius:18px;background:rgba(0,0,0,.20);padding:16px}.row{display:flex;align-items:stretch;gap:10px;margin:10px 0}.blk{flex:1;border-radius:14px;padding:14px;border:1px solid var(--line);line-height:1.45}.blue{background:rgba(125,211,252,.08);border-color:rgba(125,211,252,.32)}.purple{background:rgba(196,181,253,.08);border-color:rgba(196,181,253,.32)}.green{background:rgba(134,239,172,.08);border-color:rgba(134,239,172,.32)}.yellow{background:rgba(251,191,36,.08);border-color:rgba(251,191,36,.32)}.red{background:rgba(252,165,165,.08);border-color:rgba(252,165,165,.32)}.arr{align-self:center;font-size:24px;color:var(--yellow)}.rank{display:grid;gap:11px}.rank div{display:flex;align-items:center;gap:14px;border:1px solid var(--line);border-radius:14px;background:rgba(255,255,255,.05);padding:13px 16px;font-size:19px}.rank b{display:inline-grid;place-items:center;width:34px;height:34px;border-radius:50%;background:var(--blue);color:#06101f}.topbar{position:fixed;top:0;left:0;right:0;height:36px;background:rgba(13,17,23,.85);border-bottom:1px solid var(--line);z-index:99;display:flex;align-items:center;justify-content:space-between;padding:0 18px;color:var(--muted);font-size:12px;backdrop-filter:blur(8px)}.progress{position:fixed;top:36px;left:0;height:3px;background:linear-gradient(90deg,var(--yellow),var(--red));z-index:100;width:0}.footer{position:fixed;bottom:0;left:0;right:0;z-index:99;border-top:1px solid rgba(255,255,255,.08);padding:5px 16px;text-align:center;font-size:11px;color:#9ca3af;background:rgba(13,17,23,.88);backdrop-filter:blur(6px)}.nav{position:fixed;right:18px;bottom:42px;color:var(--muted);font-size:12px}.cover h1{font-size:58px;max-width:980px}.cover .subtitle{font-size:24px;max-width:900px}.muted{color:var(--muted)}b{color:#fff}@media (max-width: 760px){.slide{padding:54px 20px 76px;overflow-y:auto;-webkit-overflow-scrolling:touch}.slide.tight,.slide.tight.denser{padding:50px 18px 76px}.cover h1{font-size:36px}.cover .subtitle{font-size:17px}.topbar{padding:0 10px}.topbar span:last-child{display:none}.grid2,.grid3,.grid4{grid-template-columns:1fr;gap:10px}.pipeline{flex-direction:column}.pipeline b{transform:rotate(90deg);height:14px}.row{flex-direction:column}.arr{transform:rotate(90deg)}table{font-size:12px}.nav{right:12px;bottom:38px}.footer{font-size:10px}}@media print{body{overflow:visible}.slide{position:relative;display:block;page-break-after:always}.topbar,.progress,.footer,.nav{display:none}}
'''
js = r'''
const slides=[...document.querySelectorAll('.slide')];let cur=0;const curEl=document.getElementById('cur'),totEl=document.getElementById('tot'),bar=document.querySelector('.progress');function show(i){cur=Math.max(0,Math.min(slides.length-1,i));slides.forEach((s,k)=>s.classList.toggle('active',k===cur));curEl.textContent=cur+1;totEl.textContent=slides.length;bar.style.width=((cur+1)/slides.length*100)+'%';location.hash=''+(cur+1)}function next(){show(cur+1)}function prev(){show(cur-1)}document.addEventListener('keydown',e=>{if(['ArrowRight',' ','PageDown'].includes(e.key)){e.preventDefault();next()} if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();prev()} if(e.key==='Home')show(0); if(e.key==='End')show(slides.length-1); if(e.key.toLowerCase()==='p')window.print()});let touchStartX=0,touchStartY=0,touchStartT=0;document.addEventListener('touchstart',e=>{if(e.touches.length!==1)return;touchStartX=e.touches[0].clientX;touchStartY=e.touches[0].clientY;touchStartT=Date.now()},{passive:true});document.addEventListener('touchend',e=>{if(!e.changedTouches.length)return;const dx=e.changedTouches[0].clientX-touchStartX,dy=e.changedTouches[0].clientY-touchStartY,dt=Date.now()-touchStartT;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)*1.4&&dt<900){dx<0?next():prev();return}if(Math.abs(dx)<12&&Math.abs(dy)<12&&dt<350){e.changedTouches[0].clientX>window.innerWidth*0.35?next():prev()}},{passive:true});let h=parseInt(location.hash.slice(1));show(Number.isFinite(h)&&h>0?h-1:0);
'''
html_doc=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Agents for Image Restoration</title><style>{css}</style></head><body><div class="topbar"><span>Agents for Image Restoration · Recent Survey</span><span>← → 翻页 · P 打印</span></div><div class="progress"></div>{''.join(slides)}<div class="nav"><span id="cur">1</span> / <span id="tot">{len(slides)}</span></div><div class="footer"><b style="color:#e5edf7;font-weight:600;">由 DONG XINGBO 创建整理</b> · 非授权禁止转载 · © 2026 DONG XINGBO</div><script>{js}</script></body></html>'''
(out/'index.html').write_text(html_doc,encoding='utf-8')

# report md
lines=['# Agents for Image Restoration 最近工作调研','', '## TL;DR', '- 2024-2026 的主线是从 all-in-one restoration model 走向 MLLM/Agent 驱动的诊断、规划、工具调用、质量反馈闭环。', '- RestoreAgent (NeurIPS 2024) 是明确 agent 化的代表节点；2025-2026 快速扩展到 multi-agent、RL feedback、video、self-evolving、domain-specific agents。', '- 论文机会优先级: benchmark/protocol > budgeted tool routing > downstream-aware restoration agent > degradation reasoning > self-evolving memory。', '', '## 代表工作']
for w in works:
    lines.append(f'- {w[1]} {w[0]} ({w[2]}): {w[3]}')
